+---
+// A small "Open … in Lab ↗" chip for the docs/spec pages — deep-links the Lab,
+// preloaded with either an inline `grammar` (+ optional `input`) via the private
+// URL hash, or a named `preset` (calc | json | lr) the Lab loads on mount.
+import { labGrammarHref, labPresetHref } from "../lib/lab-link.ts";
+
+interface Props {
+  grammar?: string;
+  input?: string;
+  preset?: string;
+  label?: string;
+}
+const { grammar, input, preset, label } = Astro.props as Props;
+const base = import.meta.env.BASE_URL;
+const href = preset
+  ? labPresetHref(base, preset)
+  : labGrammarHref(base, grammar ?? "", input);
+const text = label ?? (preset ? `Open ${preset} in Lab ↗` : "Open in Lab ↗");
+---
+
+<a class="open-in-lab" href={href}>{text}</a>
+
+<style>
+  .open-in-lab {
+    display: inline-block;
+    font-family: var(--font-mono);
+    font-size: 0.78rem;
+    font-weight: 600;
+    color: var(--accent);
+    text-decoration: none;
+    padding: 0.2rem 0.6rem;
+    border: 1px solid var(--border-strong);
+    border-radius: var(--radius);
+    background: var(--bg-1);
+    margin: 0.15rem 0.3rem 0.15rem 0;
+  }
+  .open-in-lab:hover {
+    background: var(--accent-softer);
+    border-color: var(--accent);
+  }
+</style>

